import AppKit
import Carbon

/// macOS has no "clipboard changed" event, so poll the change counter.
@MainActor
final class ClipboardWatcher {
    // Markers password managers and similar apps put on copies that should not
    // be recorded. See nspasteboard.org.
    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    private let onCopy: (String, String?) -> Void
    private let incoming: () -> String?
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    /// `incoming` returns a clip from another device to put on the clipboard.
    init(onCopy: @escaping (_ text: String, _ sourceApp: String?) -> Void, incoming: @escaping () -> String?) {
        self.onCopy = onCopy
        self.incoming = incoming
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.5, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.check() }
        }
    }

    /// Puts text on the clipboard without recording it as a new copy.
    func put(_ text: String) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        lastChange = pasteboard.changeCount
    }

    private func check() {
        if let text = incoming() {
            put(text)
            return
        }
        let pasteboard = NSPasteboard.general
        guard pasteboard.changeCount != lastChange else { return }
        lastChange = pasteboard.changeCount

        let types = pasteboard.types ?? []
        guard !types.contains(where: { Self.ignoredTypes.contains($0.rawValue) }),
              let text = pasteboard.string(forType: .string)
        else { return }
        onCopy(text, NSWorkspace.shared.frontmostApplication?.bundleIdentifier)
    }
}

/// Posts ⌘V to the frontmost app. Needs Accessibility access.
/// Uses the key position of V on a US layout, which is also right for AZERTY
/// and QWERTZ, but not for Dvorak. Look up the layout's V key if that comes up.
func sendPasteKeystroke() {
    let source = CGEventSource(stateID: .combinedSessionState)
    let v = CGKeyCode(kVK_ANSI_V)
    for keyDown in [true, false] {
        let event = CGEvent(keyboardEventSource: source, virtualKey: v, keyDown: keyDown)
        event?.flags = .maskCommand
        event?.post(tap: .cghidEventTap)
    }
}

/// One global shortcut through Carbon, which needs no permission.
final class HotKey {
    private static var action: (() -> Void)?
    private var ref: EventHotKeyRef?

    init(keyCode: UInt32, modifiers: UInt32, action: @escaping () -> Void) {
        HotKey.action = action
        var spec = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
        InstallEventHandler(GetApplicationEventTarget(), { _, _, _ in
            HotKey.action?()
            return noErr
        }, 1, &spec, nil, nil)
        let id = EventHotKeyID(signature: OSType(0x484F_4C54), id: 1) // "HOLT"
        RegisterEventHotKey(keyCode, modifiers, id, GetApplicationEventTarget(), 0, &ref)
    }
}
